diff --git a/core/src/Kokkos_MathematicalFunctions.hpp b/core/src/Kokkos_MathematicalFunctions.hpp
index bcaa2910949..3dd6c7b8bce 100644
--- a/core/src/Kokkos_MathematicalFunctions.hpp
+++ b/core/src/Kokkos_MathematicalFunctions.hpp
@@ -208,6 +208,34 @@ using promote_3_t = typename promote_3<T, U, V>::type;
     return FUNC(static_cast<Promoted>(x), static_cast<Promoted>(y));           \
   }

+#define KOKKOS_IMPL_MATH_BINARY_PTR_FUNCTION(FUNC)                             \
+  KOKKOS_INLINE_FUNCTION float FUNC(float x, float* y) {                       \
+    using KOKKOS_IMPL_MATH_FUNCTIONS_NAMESPACE::FUNC;                          \
+    return FUNC(x, y);                                                         \
+  }                                                                            \
+  KOKKOS_INLINE_FUNCTION double FUNC(double x, double* y) {                    \
+    using KOKKOS_IMPL_MATH_FUNCTIONS_NAMESPACE::FUNC;                          \
+    return FUNC(x, y);                                                         \
+  }                                                                            \
+  KOKKOS_INLINE_FUNCTION float FUNC##f(float x, float* y) {                    \
+    using KOKKOS_IMPL_MATH_FUNCTIONS_NAMESPACE::FUNC;                          \
+    return FUNC(x, y);                                                         \
+  }                                                                            \
+  inline long double FUNC(long double x, long double* y) {                     \
+    using std::FUNC;                                                           \
+    return FUNC(x, y);                                                         \
+  }                                                                            \
+  inline long double FUNC##l(long double x, long double* y) {                  \
+    using std::FUNC;                                                           \
+    return FUNC(x, y);                                                         \
+  }                                                                            \
+  template <class T>                                                           \
+  KOKKOS_INLINE_FUNCTION std::enable_if_t<std::is_integral_v<T>, double> FUNC( \
+      T x, double* y) {                                                        \
+    using KOKKOS_IMPL_MATH_FUNCTIONS_NAMESPACE::FUNC;                          \
+    return FUNC(static_cast<double>(x), y);                                    \
+  }
+
 #define KOKKOS_IMPL_MATH_TERNARY_INT_PTR_FUNCTION(FUNC)                        \
   KOKKOS_INLINE_FUNCTION float FUNC(float x, float y, int* z) {                \
     using KOKKOS_IMPL_MATH_FUNCTIONS_NAMESPACE::FUNC;                          \
@@ -484,7 +512,7 @@ KOKKOS_IMPL_MATH_UNARY_INT_FUNCTION(llrint)
 // Floating point manipulation functions
 // frexp
 // ldexp
-// modf
+KOKKOS_IMPL_MATH_BINARY_PTR_FUNCTION(modf)
 // scalbn
 // scalbln
 KOKKOS_IMPL_MATH_UNARY_INT_FUNCTION(ilogb)
@@ -511,6 +539,7 @@ KOKKOS_IMPL_MATH_UNARY_PREDICATE(signbit)
 #undef KOKKOS_IMPL_MATH_UNARY_INT_FUNCTION
 #undef KOKKOS_IMPL_MATH_UNARY_PREDICATE
 #undef KOKKOS_IMPL_MATH_BINARY_FUNCTION
+#undef KOKKOS_IMPL_MATH_BINARY_PTR_FUNCTION
 #undef KOKKOS_IMPL_MATH_TERNARY_FUNCTION
 #undef KOKKOS_IMPL_MATH_TERNARY_INT_PTR_FUNCTION

diff --git a/core/unit_test/TestMathematicalFunctions.hpp b/core/unit_test/TestMathematicalFunctions.hpp
index 7bf9b85caed..c8403584f47 100644
--- a/core/unit_test/TestMathematicalFunctions.hpp
+++ b/core/unit_test/TestMathematicalFunctions.hpp
@@ -517,6 +517,30 @@ DEFINE_BINARY_FUNCTION_EVAL(fmin, 0);

 #undef DEFINE_BINARY_FUNCTION_EVAL

+#define DEFINE_BINARY_PTR_FUNCTION_EVAL(FUNC, ULP_FACTOR)          \
+  struct MathBinaryPtrFunction_##FUNC {                            \
+    template <typename T, typename U>                              \
+    static KOKKOS_FUNCTION auto eval(T x, U* y) {                  \
+      return Kokkos::FUNC(x, y);                                   \
+    }                                                              \
+    template <typename T, typename U>                              \
+    static auto eval_std(T x, U* y) {                              \
+      return std::FUNC(x, y);                                      \
+    }                                                              \
+    static KOKKOS_FUNCTION int ulp_factor() { return ULP_FACTOR; } \
+  };                                                               \
+  template <>                                                      \
+  struct math_function_name<MathBinaryPtrFunction_##FUNC> {        \
+    static constexpr char name[] = #FUNC;                          \
+  };                                                               \
+  constexpr char math_function_name<MathBinaryPtrFunction_##FUNC>::name[];
+
+#ifndef KOKKOS_MATHEMATICAL_FUNCTIONS_SKIP_2
+DEFINE_BINARY_PTR_FUNCTION_EVAL(modf, 0)
+#endif
+
+#undef DEFINE_BINARY_PTR_FUNCTION_EVAL
+
 #define DEFINE_TERNARY_INT_PTR_FUNCTION_EVAL(FUNC, ULP_FACTOR)              \
   struct MathTernaryIntPtrFunction_##FUNC {                                 \
     template <typename T, typename U>                                       \
@@ -759,6 +783,50 @@ struct TestMathBinaryFunction : FloatingPointComparison {
   }
 };

+template <class Space, class Func, class Arg,
+          class Ret = math_unary_function_return_type_t<Arg>>
+struct TestMathBinaryPtrFunction : FloatingPointComparison {
+  Arg val_;
+  Ret res_frac_;
+  Ret res_int_;
+  const char* m_name;
+  TestMathBinaryPtrFunction(Arg val)
+      : val_(val), m_name(math_function_name<Func>::name) {
+    res_frac_ = Func::eval_std(val_, &res_int_);
+    run();
+  }
+  void run() {
+    int errors = 0;
+    Kokkos::parallel_reduce(Kokkos::RangePolicy<Space>(0, 1), *this, errors);
+    ASSERT_EQ(errors, 0) << "Failed " << m_name << " check for "
+                         << type_helper<Arg>::name();
+  }
+  KOKKOS_FUNCTION void operator()(int, int& e) const {
+    Ret iptr;
+    Ret frac     = Func::eval(val_, &iptr);
+    bool ar_frac = compare(frac, res_frac_, Func::ulp_factor());
+    bool ar_int  = compare(iptr, res_int_, Func::ulp_factor());
+    if (!ar_frac || !ar_int) {
+      ++e;
+      Kokkos::printf("%s failed: Val %f -> Frac %f (exp %f), Int %f (exp %f)\n",
+                     m_name, (double)val_, (double)frac, (double)res_frac_,
+                     (double)iptr, (double)res_int_);
+    }
+  }
+};
+
+template <class Space, class... Func, class Arg>
+void do_test_math_binary_ptr_function(Arg x) {
+  (void)std::initializer_list<int>{
+      (TestMathBinaryPtrFunction<Space, Func, Arg>(x), 0)...};
+  if constexpr (!std::is_same_v<Space, Kokkos::DefaultHostExecutionSpace>) {
+    (void)std::initializer_list<int>{(
+        TestMathBinaryPtrFunction<Kokkos::DefaultHostExecutionSpace, Func, Arg>(
+            x),
+        0)...};
+  }
+}
+
 template <class Space, class... Func, class Arg1, class Arg2>
 void do_test_math_binary_function(Arg1 arg1, Arg2 arg2) {
   (void)std::initializer_list<int>{
@@ -1010,6 +1078,18 @@ TEST(TEST_CATEGORY, mathematical_functions_power_functions) {
 #endif
 }

+TEST(TEST_CATEGORY, mathematical_functions_modf) {
+  using Func = MathBinaryPtrFunction_modf;
+
+  do_test_math_binary_ptr_function<TEST_EXECSPACE, Func>(42.765f);
+  do_test_math_binary_ptr_function<TEST_EXECSPACE, Func>(-15.123);
+  do_test_math_binary_ptr_function<TEST_EXECSPACE, Func>(15);
+
+#ifdef MATHEMATICAL_FUNCTIONS_HAVE_LONG_DOUBLE_OVERLOADS
+  do_test_math_binary_ptr_function<TEST_EXECSPACE, Func>(1234.5678l);
+#endif
+}
+
 TEST(TEST_CATEGORY, mathematical_functions_fma) {
   do_test_math_ternary_function<TEST_EXECSPACE, kk3_fma>(2.f, 3.f, 4.f);
   do_test_math_ternary_function<TEST_EXECSPACE, kk3_fma>(2., 3., 4.);

